"""Editorial reference layout, retaining each article's verified content and tools."""
import json
from urllib.parse import quote

def render(p,g):
 a,e,image,icon,url,ext=[g[k] for k in ['a','e','image','icon','url','ext']]
 b=next(x for x in g['B']['blog_plan'] if x['id']==p['id']);slug,item,d,minutes=g['guide_info'](b);target=b['commercial_target'];hotels=g['HOTELS'];choose=slug=='choose-area'
 hid=d.get('hotel') or next((h for h in hotels if target==h or target.startswith(h+'_')),None)
 if target=='longstay':hid='petrovsky'
 ids=[hid] if hid else ['tverskaya','lubyansky'] if target=='family' else list(hotels)
 asset=g['guide_asset'](b);photo_hotel=next(h for h in hotels if asset.startswith(h))
 caption=hotels[photo_hotel]['full']+' · '+('ИИ-реконструкция фасада' if g['DELIVERY'].get(asset,{}).get('label') else 'фасад' if asset in hotels else g['room_name'](g['PAGES'][asset]))
 intro='Сравниваем четыре адреса Туррис: по маршрутам, планам и условиям проживания.' if choose else d['takeaways'][0]+' '+d['takeaways'][1]
 cover='<figure class="guide-cover">'+image(asset,caption,eager=True,sizes='(max-width:640px) 92px, (max-width:900px) 36vw, 550px')+'<figcaption>'+caption+'</figcaption></figure>'
 head='<header class="guide-article-head"><div><div class="eyebrow">'+a('blog','Гид по Москве')+' · '+a('blog_'+b['rubric'],g['RUBRIC_LABELS'][b['rubric']])+'</div><h1>'+e(p['h1'])+'</h1><p class="ar-intro">'+intro+'</p><div class="guide-byline"><span>Редакция Туррис · прототип</span><time datetime="2026-10-29">Обновлено 29 октября 2026</time><span>'+str(minutes)+' мин чтения</span></div><div class="guide-tools"><a href="#article-summary">'+icon('arrow')+'Краткий ответ ↓</a><a href="#article-checklist">'+icon('check')+'К чек-листу ↓</a><button type="button" data-copy-article>'+icon('document')+'Скопировать ссылку</button><span role="status" data-copy-status></span></div></div>'+cover+'</header>'
 summary='<section class="guide-answer" id="article-summary"><div class="eyebrow">Коротко о главном</div><h2>'+('Выбирайте отель по маршрутам вашей поездки.' if choose else e(d['takeaways'][0]))+'</h2><p>'+e(item['answer'])+'</p><ol>'+''.join('<li><span>'+str(n).zfill(2)+'</span>'+e(t)+'</li>' for n,t in enumerate(d['takeaways'],1))+'</ol></section>'
 toc_items=[('article-choice','Сравнение расположений' if choose else d['table_title']),('article-map','Отели на карте')]+([('article-route','Опорные точки прогулки')] if 'stops' in d else [])+[('part-'+str(n),h) for n,(h,t) in enumerate(item['sections'],1)]+[('article-checklist','Чек-лист'),('article-sources','Источники')]
 toc='<details class="guide-toc" open><summary>В этой статье <span>⌄</span></summary><nav aria-label="Содержание статьи">'+''.join('<a href="#'+anchor+'" data-toc-link>'+e(title)+'<span aria-hidden="true">⌄</span></a>' for anchor,title in toc_items)+'</nav></details>'
 headings=['Отель и адрес','Когда рассмотреть','Что проверить'] if choose else ['Ситуация','Что сделать','Что проверить']
 if choose:
  scenarios=['Поездка связана с Белорусским вокзалом.','Планы вокруг Китай-города и Зарядья.','Прогулки по бульварам.','Маршруты по набережным и Таганке.']
  rows=''.join('<tr><th scope="row">'+a(h,hotels[h]['name'])+'<small>'+hotels[h]['address']+'</small></th><td data-label="Когда рассмотреть">'+scenarios[n]+'</td><td data-label="Что проверить">'+e(d['rows'][n][2])+'</td></tr>' for n,h in enumerate(hotels))
 else:rows=''.join('<tr><th scope="row">'+e(row[0])+'</th><td data-label="Что сделать">'+e(row[1])+'</td><td data-label="Что проверить">'+e(row[2])+'</td></tr>' for row in d['rows'])
 table='<section class="ar-section" id="article-choice" data-reading-section><h2>'+e(d['table_title'])+'</h2>'+('<p class="ar-sub">Сопоставьте расположение отеля со своими планами.</p>' if choose else '')+'<div class="ar-table-wrap"><table class="guide-table"><caption class="sr-only">'+e(d['table_title'])+'</caption><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headings)+'</tr></thead><tbody>'+rows+'</tbody></table></div>'+a(target,'Сравнить условия отелей '+icon('arrow') if choose else 'Посмотреть варианты по теме '+icon('arrow'),'text-link')+'</section>'
 config={h:dict(g['MAP']['hotels'][h],name=hotels[h]['name']) for h in ids}
 buttons='';panels=''
 for n,h in enumerate(ids,1):
  hotel=hotels[h];geo=config[h]
  buttons+='<button type="button" class="map-choice" data-map-select="'+h+'" aria-pressed="false"><span class="map-number">'+str(n).zfill(2)+'</span><span>'+hotel['name']+'<small>'+hotel['location']+'</small></span></button>'
  panels+='<article class="map-detail" data-map-detail="'+h+'">'+image(h,'Фасад отеля '+hotel['full'])+'<div class="map-detail-copy"><h3>'+hotel['full']+'</h3><p class="address">'+icon('pin')+hotel['address']+'</p><p class="map-condition">'+hotel['notice']+'</p>'+a(h+'_rooms','Посмотреть номера '+icon('arrow'),'btn full')+'<div class="map-actions">'+ext(geo['source']+'?rtext=~'+str(geo['lat'])+','+str(geo['lng']),'Построить маршрут')+a(h+'_contacts','Как добраться','text-link')+'</div></div></article>'
 maphtml='<section class="ar-section" id="article-map" data-reading-section><h2>'+('Отправная точка вашей прогулки' if 'stops' in d else 'Сравните расположение на карте' if len(ids)>1 else 'Расположение отеля')+'</h2><p class="ar-sub">'+('На карте отмечен отель. Пешеходный путь к достопримечательности — по ссылке в следующем блоке.' if 'stops' in d else 'Выберите отель, чтобы посмотреть адрес и построить маршрут.')+'</p><div class="hotel-map ar-map" id="map" data-hotel-map data-selected="'+ids[0]+'" data-tile-url="'+g['MAP']['tile_url']+'" style="--map-count:'+str(len(ids))+'"><div class="map-choices" aria-label="Выберите отель">'+buttons+'</div><div class="map-layout"><div class="map-stage"><div class="map-canvas" data-map-canvas role="region" aria-label="Карта отелей из статьи"></div><div class="map-toolbar"><span>Москва · '+str(len(ids))+' '+('адрес' if len(ids)==1 else 'адреса')+'</span><button type="button" data-map-reset>Все отели '+icon('pin')+'</button></div><p class="map-status" data-map-status role="status">Загружаем карту… Адреса и маршруты доступны рядом.</p></div><div class="map-details">'+panels+'</div></div><span class="sr-only" data-map-announcement aria-live="polite"></span><script type="application/json" data-map-config>'+json.dumps(config,ensure_ascii=False)+'</script></div></section>'
 route=''
 if 'stops' in d:
  route_url='https://yandex.ru/maps/?mode=routes&rtt=pd&rtext='+quote('Москва, '+hotels[d['hotel']]['address']+'~'+d['destination'],safe='')
  route='<section class="ar-section ar-route" id="article-route" data-reading-section><h2>Опорные точки прогулки</h2><p class="ar-sub">Переходы, ограничения и время в пути проверьте по актуальной карте перед выходом.</p><ol>'+''.join('<li><span>'+str(n).zfill(2)+'</span><div><h3>'+e(h)+'</h3><p>'+e(t)+'</p></div></li>' for n,(h,t) in enumerate(d['stops'],1))+'</ol>'+ext(route_url,'Построить пешеходный маршрут','btn secondary')+'</section>'
 steps='<section class="ar-section ar-steps"><h2>'+('С чего начать выбор района' if choose else 'Разберём по шагам')+'</h2><ol>'+''.join('<li id="part-'+str(n)+'" data-reading-section><span>'+str(n).zfill(2)+'</span><div><h3>'+e(h)+'</h3><p>'+e(t)+'</p>'+('<div class="ar-context-links">'+a('family','Размещение с детьми '+icon('arrow'),'text-link')+a('business','Для командировок '+icon('arrow'),'text-link')+'</div>' if choose and n==3 else '')+'</div></li>' for n,(h,t) in enumerate(item['sections'],1))+'</ol></section>'
 tip='<aside class="guide-tip">'+icon('pin')+'<div><span>Практический совет</span><p>'+e(d['tip'])+'</p></div></aside>'
 checklist='<section class="guide-checklist" id="article-checklist" data-reading-section data-guide-checklist="'+slug+'"><div class="ar-check-intro"><h2>Проверьте перед поездкой</h2><span data-check-count aria-live="polite">Готово: 0 из '+str(len(d['checklist']))+'</span><progress data-check-progress max="'+str(len(d['checklist']))+'" value="0" aria-label="Выполнение чек-листа"></progress></div><div class="ar-check-items">'+''.join('<label><input type="checkbox" data-guide-check="'+str(n)+'"><span>'+e(t)+'</span></label>' for n,t in enumerate(d['checklist']))+'</div><div class="ar-check-actions"><button type="button" data-check-reset>Сбросить отметки</button><p>Отметки сохраняются в этой вкладке.</p></div></section>'
 booking=g['booking_form'](hid or '')
 for label,ic in [('Отель','pin'),('Даты поездки','calendar'),('Гости','guest')]:
  booking=booking.replace('>'+label+'<','><span class="ar-field-icon">'+icon(ic)+'</span><span class="ar-field-label">'+('Заезд — Выезд' if label=='Даты поездки' else label)+'</span><')
 booking='<section class="ar-booking" id="article-booking"><h2>'+('Выбрали расположение? Найдите номер на ваши даты' if choose else 'От планов — к вашей поездке')+'</h2><p>Выберите отель, даты и гостей. Наличие и стоимость уточняются в официальном тарифе.</p>'+booking+'<p class="ar-booking-note">'+icon('document')+'Стоимость, питание и условия отмены — в выбранном тарифе.</p>'+(' <div class="ar-booking-target">'+a(target,'Условия по теме статьи '+icon('arrow'),'text-link')+'</div>' if target not in hotels and target!='hotels' else '')+'</section>'
 source_hotels=ids
 sources=''.join('<li>'+ext('https://turris.online'+g['PAGES'][h]['url'],hotels[h]['full'])+'</li>' for h in source_hotels)
 if d.get('source'):
  title,href=g['GUIDE_SOURCES'][d['source']];sources+='<li>'+ext(href,title)+'</li>'
 sources='<section class="guide-sources" id="article-sources" data-reading-section><div><h2>Источники и актуальность</h2><p>Сведения об отелях — на официальных страницах Туррис. Проверено 28–29 октября 2026.</p></div><div><ul>'+sources+'</ul><p class="ar-source-note">Маршрут и чек-лист — рекомендации редакции. Расписание, правила посещения и условия проживания проверяйте на дату поездки.</p></div></section>'
 related=[x for x in g['B']['blog_plan'] if x['id']!=b['id'] and x['rubric']==b['rubric']][:3]
 if len(related)<3:related += [x for x in g['B']['blog_plan'] if x['id']!=b['id'] and x not in related][:3-len(related)]
 cards=''.join('<article class="ar-related-card"><a href="'+url(x['id'])+'">'+image(g['guide_asset'](x),x['title'],sizes='(max-width:640px) calc(100vw - 32px), 390px')+'</a><div><h3>'+a(x['id'],x['title'])+'</h3>'+a(x['id'],'Маршрут и советы '+icon('arrow') if 'stops' in g['guide_info'](x)[2] else 'Практические советы '+icon('arrow'),'text-link')+'</div></article>' for x in related)
 relatedhtml='<section class="ar-section ar-related"><h2>Продолжите планировать поездку</h2><div>'+cards+'</div></section>'
 return '<article class="wrap guide-article article-page" data-guide-article>'+head+'<div class="ar-overview">'+summary+toc+'</div>'+table+maphtml+route+steps+tip+checklist+booking+sources+relatedhtml+'</article>'
